Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='prefetchinputs', at=datetime(2026, 11, 15, 0, 0, 0), actor='assistant', title="A cloud session prefetches the flake's inputs before its first Nix command", body='A coding session in the cloud runs scripts/prefetch-inputs.sh before its first Nix command, and again after a merge that moves flake.lock. When a Nix command still fails, the pull request says so, names the command that could not run, and does not claim its check.', rationale="The cloud environment's proxy refuses the tarballs Nix fetches for GitHub inputs, so nix develop and nix build failed until the inputs were put in the store by git; sessions then reported checks as passed that had not run.", supersedes=()))